    '2008 Financial Crisis': ('2007-10-01', '2009-03-31'),
    '2020 COVID-19 Crash': ('2020-01-01', '2020-03-31'),
}

crisis_results = []
for name, (start, end) in crisis_periods.items():
    period_data = df[(df['Date'] >= start) & (df['Date'] <= end)]
    if len(period_data) < 10:
        continue

    start_price = period_data['Close'].iloc[0]
    end_price = period_data['Close'].iloc[-1]
    period_return = ((end_price / start_price) - 1) * 100
    period_vol = period_data['Daily_Return'].std() * np.sqrt(252) * 100

    period_data = period_data.copy()
    period_data['Cummax'] = period_data['Close'].cummax()
    period_data['Drawdown'] = (period_data['Close'] - period_data['Cummax']) / period_data['Cummax'] * 100
    max_dd = period_data['Drawdown'].min()
