        'date': row['Date'].strftime('%Y-%m-%d'),
        'ratio': row['Stock Splits']
    })

print(f"Dividend events: {total_dividend_events}")
print(f"Split events: {len(split_events)}")

# ============ CHART DATA ============

sample_interval = max(1, len(df) // 400)
sampled_df = df.iloc[::sample_interval].copy()

price_history = []
for _, row in sampled_df.iterrows():
