# ============ BULL/BEAR PHASES ============

# Find major bull phases (sustained uptrends)
bull_phases = []
bear_phases = []

# Rolling 252-day max
df['RollingMax'] = df['Close'].rolling(window=252, min_periods=1).max()
df['RollingMaxDate'] = df['Date']

# Find peaks and troughs
data_reset = df.reset_index(drop=True)
troughs = []
peaks = []

for i in range(252, len(data_reset)):
