    window_max = window_data['Close'].max()
    window_min = window_data['Close'].min()

    # Check if this is a local peak (within 10% of rolling max)
    if current_price >= window_max * 0.98:  # Near peak
        peaks.append({
            'date': data_reset.iloc[i]['Date'],
            'price': current_price,
            'idx': i
        })

    if current_price <= window_min * 1.02:  # Near trough
        troughs.append({
            'date': data_reset.iloc[i]['Date'],
