volume_data = df[df['Volume'] > 0].copy()
volume_by_decade = volume_data.groupby('Decade')['Volume'].mean().reset_index()
volume_by_decade.columns = ['Decade', 'Avg_Volume']
volume_by_decade['Decade'] = volume_by_decade['Decade'].apply(lambda x: f"{x}s")

volume_threshold = volume_data['Volume'].quantile(0.99)
volume_spikes = volume_data[volume_data['Volume'] > volume_threshold].nlargest(10, 'Volume')

# ============ DIVIDEND & SPLIT EVENTS ============

dividend_events = df[df['Dividends'] > 0].copy()
