for _, row in split_events.iterrows():
    split_list.append({
        'date': row['Date'].strftime('%Y-%m-%d'),
        'ratio': row['Stock Splits']
    })

print(f"Dividend events: {total_dividend_events}")
print(f"Split events: {len(split_events)}")

# ============ CHART DATA ============

sample_interval = max(1, len(df) // 400)
sampled_df = df.iloc[::sample_interval].copy()

price_history = []
for _, row in sampled_df.iterrows():
    price_history.append({
        'date': row['Date'].strftime('%Y-%m-%d'),
        'close': round(row['Close'], 4),
        'volume': int(row['Volume']) if row['Volume'] > 0 else None,
        'drawdown': round(row['Drawdown'], 2) if 'Drawdown' in row else 0
    })

# ============ BULL/BEAR PHASES ============

# Find major bull phases (sustained uptrends)
bull_phases = []
bear_phases = []

# Rolling 252-day max
df['RollingMax'] = df['Close'].rolling(window=252, min_periods=1).max()
df['RollingMaxDate'] = df['Date']

# Find peaks and troughs
data_reset = df.reset_index(drop=True)
troughs = []
peaks = []

for i in range(252, len(data_reset)):
    window_data = data_reset.iloc[i-252:i+1]
    current_price = data_reset.iloc[i]['Close']
    window_max = window_data['Close'].max()
    window_min = window_data['Close'].min()

    # Check if this is a local peak (within 10% of rolling max)
    if current_price >= window_max * 0.98:  # Near peak
        peaks.append({
            'date': data_reset.iloc[i]['Date'],
            'price': current_price,
            'idx': i
        })

    if current_price <= window_min * 1.02:  # Near trough
        troughs.append({
            'date': data_reset.iloc[i]['Date'],
            'price': current_price,
            'idx': i
        })

# Simple peak-trough analysis
major_events = []
if len(peaks) > 0 and len(troughs) > 0:
    # Find major peaks (top 20 by price)
    top_peaks = sorted(peaks, key=lambda x: x['price'], reverse=True)[:15]
    major_events.append({'type': 'peak', 'date': top_peaks[0]['date'], 'price': top_peaks[0]['price']})

    # Find major troughs (bottom 20 by price)
    bottom_troughs = sorted(troughs, key=lambda x: x['price'])[:10]
