# Load data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'].str.replace(r'-\d{2}:\d{2}$', '', regex=True))
df = df.sort_values('Date').reset_index(drop=True)

print(f"Data loaded: {len(df)} rows")
print(f"Date range: {df['Date'].min()} to {df['Date'].max()}")

# ============ KPI CALCULATIONS ============

first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
years = (last_date - first_date).days / 365.25

cumulative_return = ((last_close / first_close) - 1) * 100
cagr = ((last_close / first_close) ** (1/years) - 1) * 100

df['Cummax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Cummax']) / df['Cummax'] * 100
max_drawdown = df['Drawdown'].min()
max_drawdown_idx = df['Drawdown'].idxmin()
drawdown_start_idx = df.loc[:max_drawdown_idx, 'Close'].idxmax()
drawdown_start_date = df.loc[drawdown_start_idx, 'Date']
drawdown_start_price = df.loc[drawdown_start_idx, 'Close']
drawdown_end_date = df.loc[max_drawdown_idx, 'Date']
drawdown_end_price = df.loc[max_drawdown_idx, 'Close']

daily_volatility = df['Close'].pct_change().std()
annualized_volatility = daily_volatility * np.sqrt(252) * 100
total_dividends = df['Dividends'].sum()

ath_price = df['Close'].max()
ath_date = df.loc[df['Close'].idxmax(), 'Date']
atl_price = df['Close'].min()
atl_date = df.loc[df['Close'].idxmin(), 'Date']

# ============ DECADE ANALYSIS ============

df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10
df['Daily_Return'] = df['Close'].pct_change()

decade_stats = []
for decade in sorted(df['Decade'].unique()):
    decade_data = df[df['Decade'] == decade]
    if len(decade_data) < 50:
        continue

    start_price = decade_data['Close'].iloc[0]
    end_price = decade_data['Close'].iloc[-1]
    start_date = decade_data['Date'].iloc[0]
    end_date = decade_data['Date'].iloc[-1]

    if decade == 1970 and start_date.year < 1975:
        decade_data = decade_data[decade_data['Year'] >= 1972]
        if len(decade_data) < 50:
            continue
        start_price = decade_data['Close'].iloc[0]
        start_date = decade_data['Date'].iloc[0]

    decade_return = ((end_price / start_price) - 1) * 100
    decade_vol = decade_data['Daily_Return'].std() * np.sqrt(252) * 100
    decade_divs = decade_data['Dividends'].sum()
    decade_high = decade_data['Close'].max()
    decade_low = decade_data['Close'].min()
    ath_in_decade = decade_data['Close'].idxmax()
    atl_in_decade = decade_data['Close'].idxmin()

    decade_stats.append({
        'decade': f"{decade}s",
        'start_year': start_date.year,
        'end_year': end_date.year,
        'start_price': round(start_price, 4),
        'end_price': round(end_price, 2),
        'return_pct': round(decade_return, 2),
        'volatility': round(decade_vol, 2),
        'dividends': round(decade_divs, 4),
        'high': round(decade_high, 2),
        'high_date': decade_data.loc[ath_in_decade, 'Date'].strftime('%Y-%m-%d'),
        'low': round(decade_low, 4),
        'low_date': decade_data.loc[atl_in_decade, 'Date'].strftime('%Y-%m-%d'),
        'trading_days': len(decade_data)
    })

print(f"Decade stats computed: {len(decade_stats)} decades")

# ============ CRISIS ANALYSIS ============

crisis_periods = {
    '1973-74 Oil Crisis': ('1973-01-01', '1974-12-31'),
    '1987 Black Monday': ('1987-01-01', '1987-12-31'),
    '2000-02 Dot-com Bust': ('1999-01-01', '2002-12-31'),
    '2008 Financial Crisis': ('2007-10-01', '2009-03-31'),
    '2020 COVID-19 Crash': ('2020-01-01', '2020-03-31'),
}

crisis_results = []
for name, (start, end) in crisis_periods.items():
    period_data = df[(df['Date'] >= start) & (df['Date'] <= end)]
    if len(period_data) < 10:
        continue

    start_price = period_data['Close'].iloc[0]
    end_price = period_data['Close'].iloc[-1]
    period_return = ((end_price / start_price) - 1) * 100
    period_vol = period_data['Daily_Return'].std() * np.sqrt(252) * 100

    period_data = period_data.copy()
    period_data['Cummax'] = period_data['Close'].cummax()
    period_data['Drawdown'] = (period_data['Close'] - period_data['Cummax']) / period_data['Cummax'] * 100
    max_dd = period_data['Drawdown'].min()
    max_dd_date = period_data.loc[period_data['Drawdown'].idxmin(), 'Date']

    crisis_results.append({
        'name': name,
        'start': start,
        'end': end,
        'start_price': round(start_price, 2),
        'end_price': round(end_price, 2),
        'return': round(period_return, 2),
        'max_drawdown': round(max_dd, 2),
        'max_drawdown_date': max_dd_date.strftime('%Y-%m-%d'),
        'volatility': round(period_vol, 2)
    })

print(f"Crisis analysis computed: {len(crisis_results)} periods")

# ============ VOLUME ANALYSIS ============

volume_data = df[df['Volume'] > 0].copy()
